import warnings
from decimal import Decimal, InvalidOperation


def sum_amount(path):
    """Sum finite Decimal amounts, warning once per malformed record skipped."""
    total = Decimal(0)
    with open(path, encoding="utf-8-sig", newline="") as source:
        reader = csv.reader(source, strict=True)
        header = next(reader, [])
        if header.count("amount") != 1:
            raise ValueError("CSV header must contain exactly one 'amount' column")
        column = header.index("amount")
        while True:
            line = reader.line_num + 1
            try:
                row = next(reader)
            except StopIteration:
                break
            except csv.Error as error:
                warnings.warn(f"Skipping CSV record at line {line}: {error}", stacklevel=2)
                continue
            if not row:
                continue
            if len(row) != len(header):
                warnings.warn(f"Skipping CSV record at line {line}: wrong field count", stacklevel=2)
                continue
            try:
                amount = Decimal(row[column].strip())
            except InvalidOperation:
                amount = Decimal('NaN')
            if not amount.is_finite():
                warnings.warn(f"Skipping CSV record at line {line}: invalid amount", stacklevel=2)
                continue
            total += amount
    return total
